import sys

def is_regular_bracket_sequence(s):
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def solve():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    results = []
    for i in range(1, t + 1):
        s = input[i]
        open_count = s.count('(')
        close_count = s.count(')')
        question_marks = len(s) - open_count - close_count

        # We need to ensure that we can balance the sequence
        # by replacing '?' with '(' or ')'
        if open_count > 1 or close_count > 1:
            results.append("NO")
            continue

        # If there's only one '(' and one ')', we need to check if we can balance
        # the sequence by replacing '?' appropriately
        if open_count == 1 and close_count == 1:
            # Try to replace '?' with '(' or ')' and check if it forms a valid RBS
            balance = 0
            for char in s:
                if char == '(':
                    balance += 1
                elif char == ')':
                    balance -= 1
                elif char == '?':
                    if balance >= 0:
                        balance += 1
                    else:
                        balance -= 1
                if balance < 0:
                    break
            if balance == 0:
